-- 1215: C811 -- clear the REMAINING PL-7001 Power Apps leftovers.
--
-- Follow-up to 1214. Migration 1210 renamed the course and 1214 replaced the
-- overview + outline, but an audit of every EAV field on entity 811 found four
-- more attributes still describing the old Power Apps course. All are
-- outward-facing:
--
--   meta_keyword       -- "Power Apps canvas apps, PL-7001 Power Apps, ..."
--   meta_description   -- "Learn to build, customize, and manage canvas apps..."
--   whoshouldattend    -- 20 Power Apps / Power Platform job titles, rendered
--                         as the visible "Who Should Attend" list
--   *_label            -- image/small_image/thumbnail alt text reading
--                         "PL-7001 Create and manage canvas apps with Power Apps"
--
-- prerequisite is also corrected: it required installing Visual Studio
-- Community, which is meaningless for a one-day job-redesign workshop, and its
-- "GCE 'O' Levels" line carried invalid-UTF-8 curly quotes (mojibake on the
-- live page). Entities used instead.
--
-- NOT touched: name, url_key, meta_title and course_image_url are already
-- correct from 1210 (the R2 cover was regenerated). The media_gallery FILE
-- path stays as-is -- renaming the stored file is a media operation, not a DB
-- one; only its display label is corrected here.
--
-- All payloads are HEX to preserve bytes, and all are pure ASCII (entities, no
-- raw Unicode) so apply.php's utf8 connection is safe.
--
-- SG-guarded; C-prefix SKU is SG-only (partner no-op). Idempotent.

SET @is_sg := (
  SELECT COUNT(*) FROM core_config_data
  WHERE path = 'web/unsecure/base_url'
    AND value LIKE '%tertiarycourses.com.sg%'
);

SET @e811 := (SELECT entity_id FROM catalog_product_entity WHERE sku = 'C811' LIMIT 1);

SET @a_kw   := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'meta_keyword');
SET @a_md   := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'meta_description');
SET @a_wsa  := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'whoshouldattend');
SET @a_pre  := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'prerequisite');

-- ---------------------------------------------------------------------------
-- 1) Text attributes: meta_keyword, whoshouldattend, prerequisite.
-- ---------------------------------------------------------------------------

INSERT INTO catalog_product_entity_text (entity_type_id, attribute_id, store_id, entity_id, value)
SELECT 4, @a_kw, 0, @e811, CONVERT( USING utf8)
FROM dual WHERE @e811 IS NOT NULL AND @a_kw IS NOT NULL AND @is_sg > 0
ON DUPLICATE KEY UPDATE value = VALUES(value);

INSERT INTO catalog_product_entity_text (entity_type_id, attribute_id, store_id, entity_id, value)
SELECT 4, @a_wsa, 0, @e811, CONVERT( USING utf8)
FROM dual WHERE @e811 IS NOT NULL AND @a_wsa IS NOT NULL AND @is_sg > 0
ON DUPLICATE KEY UPDATE value = VALUES(value);

INSERT INTO catalog_product_entity_text (entity_type_id, attribute_id, store_id, entity_id, value)
SELECT 4, @a_pre, 0, @e811, CONVERT( USING utf8)
FROM dual WHERE @e811 IS NOT NULL AND @a_pre IS NOT NULL AND @is_sg > 0
ON DUPLICATE KEY UPDATE value = VALUES(value);

DELETE FROM catalog_product_entity_text
WHERE entity_id = @e811 AND store_id <> 0
  AND attribute_id IN (@a_kw, @a_wsa, @a_pre)
  AND @e811 IS NOT NULL AND @is_sg > 0;

-- ---------------------------------------------------------------------------
-- 2) meta_description lives in the VARCHAR table on this install.
-- ---------------------------------------------------------------------------

INSERT INTO catalog_product_entity_varchar (entity_type_id, attribute_id, store_id, entity_id, value)
SELECT 4, @a_md, 0, @e811, CONVERT( USING utf8)
FROM dual WHERE @e811 IS NOT NULL AND @a_md IS NOT NULL AND @is_sg > 0
ON DUPLICATE KEY UPDATE value = VALUES(value);

DELETE FROM catalog_product_entity_varchar
WHERE entity_id = @e811 AND attribute_id = @a_md AND store_id <> 0
  AND @e811 IS NOT NULL AND @is_sg > 0;

-- ---------------------------------------------------------------------------
-- 3) Gallery / image alt-text labels.
-- ---------------------------------------------------------------------------

UPDATE catalog_product_entity_varchar v
   JOIN eav_attribute a ON a.attribute_id = v.attribute_id
    SET v.value = CONVERT(0x4A6F62204173736573736D656E7420616E6420526564657369676E20666F722041492041646F7074696F6E USING utf8)
 WHERE v.entity_id = @e811
   AND a.entity_type_id = 4
   AND a.attribute_code IN ('image_label', 'small_image_label', 'thumbnail_label')
   AND @e811 IS NOT NULL AND @is_sg > 0;

UPDATE catalog_product_entity_media_gallery_value gv
   JOIN catalog_product_entity_media_gallery g ON g.value_id = gv.value_id
    SET gv.label = CONVERT(0x4A6F62204173736573736D656E7420616E6420526564657369676E20666F722041492041646F7074696F6E USING utf8)
 WHERE g.entity_id = @e811
   AND @e811 IS NOT NULL AND @is_sg > 0;

-- ---------------------------------------------------------------------------
-- 4) Mirror the flat columns so the storefront reads the new values without
--    waiting on a reindex. Guarded on column existence (meta_title has no flat
--    column on this install -- see memory feedback_meta_title_flat_has_no_column).
-- ---------------------------------------------------------------------------

SET @has_md := (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'catalog_product_flat_1' AND COLUMN_NAME = 'meta_description');
SET @sql := IF(@has_md > 0 AND @e811 IS NOT NULL AND @is_sg > 0,
  'UPDATE catalog_product_flat_1 f JOIN catalog_product_entity_varchar v
      ON v.entity_id = f.entity_id AND v.store_id = 0 AND v.attribute_id = @a_md
     SET f.meta_description = v.value WHERE f.entity_id = @e811',
  'DO 0');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

SET @has_wsa := (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'catalog_product_flat_1' AND COLUMN_NAME = 'whoshouldattend');
SET @sql := IF(@has_wsa > 0 AND @e811 IS NOT NULL AND @is_sg > 0,
  'UPDATE catalog_product_flat_1 f JOIN catalog_product_entity_text t
      ON t.entity_id = f.entity_id AND t.store_id = 0 AND t.attribute_id = @a_wsa
     SET f.whoshouldattend = t.value WHERE f.entity_id = @e811',
  'DO 0');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

SET @has_pre := (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'catalog_product_flat_1' AND COLUMN_NAME = 'prerequisite');
SET @sql := IF(@has_pre > 0 AND @e811 IS NOT NULL AND @is_sg > 0,
  'UPDATE catalog_product_flat_1 f JOIN catalog_product_entity_text t
      ON t.entity_id = f.entity_id AND t.store_id = 0 AND t.attribute_id = @a_pre
     SET f.prerequisite = t.value WHERE f.entity_id = @e811',
  'DO 0');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
